mapper.select:
select * from ( select sm.*, m.machine_code, m.machine_name from T_GSQ_TWINING_DISC sm left join T_GSQ_MACHINE_INFO m on sm.machine_id = m.id where sm.DEL_FLAG = 0 and m.DEL_FLAG = 0
and INSTR(SERIAL_NUMBER, #{serialNumber}) > 0
and INSTR(order_way, #{orderWay}) > 0
AND instr(name, #{name} )>0
AND MACHINE_ID = #{machineId}
order by sm.create_time desc
) t
order by ${orderStr}

mapper.update:
update t_gsq_twining_disc
serial_number = #{serialNumber}, name = #{name}, seq = #{seq}, purpose = #{purpose}, spec = #{spec}, order_way = #{orderWay}, twining_num = #{twiningNum,jdbcType=DECIMAL}, in_time = #{inTime,jdbcType=DATE}, scrap_time = #{scrapTime,jdbcType=DATE}, scrap_reason = #{scrapReason}, machine_id = #{machineId}, del_flag = #{delFlag}, remark = #{remark}, create_by = #{createBy}, create_time = #{createTime}, update_by = #{updateBy}, update_time = #{updateTime},
where id = #{id}

merge into T_GSQ_TWINING_DISC a USING (
select #{twiningDisc.serialNumber,jdbcType=VARCHAR} serial_number, #{twiningDisc.name,jdbcType=VARCHAR} name, #{twiningDisc.seq,jdbcType=DOUBLE} seq, #{twiningDisc.purpose,jdbcType=VARCHAR} purpose, #{twiningDisc.spec,jdbcType=VARCHAR} spec, #{twiningDisc.orderWay,jdbcType=VARCHAR} order_way, #{twiningDisc.twiningNum,jdbcType=DOUBLE} twining_num, #{twiningDisc.inTime,jdbcType=DATE} in_time, #{twiningDisc.scrapTime,jdbcType=DATE} scrap_time, #{twiningDisc.scrapReason,jdbcType=VARCHAR} scrap_reason, #{twiningDisc.machineId,jdbcType=DOUBLE} machine_id, #{twiningDisc.createBy,jdbcType=VARCHAR} create_by, #{twiningDisc.createTime,jdbcType=DATE} create_time, #{twiningDisc.updateBy,jdbcType=VARCHAR} update_by, #{twiningDisc.updateTime,jdbcType=DATE} update_time, #{twiningDisc.remark,jdbcType=VARCHAR} remark from dual
) b ON ( a.serial_number = b.serial_number AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.name = b.name, a.seq = b.seq, a.purpose = b.purpose, a.spec = b.spec, a.order_way = b.order_way, a.twining_num = b.twining_num, a.in_time = b.in_time, a.scrap_time = b.scrap_time, a.scrap_reason = b.scrap_reason, a.machine_id = b.machine_id, a.update_by = b.create_by, a.update_time = sysdate, a.remark = b.remark WHEN NOT MATCHED THEN INSERT ( a.id, a.name, a.seq, a.purpose, a.spec, a.order_way, a.twining_num, a.in_time, a.scrap_time, a.scrap_reason, a.machine_id, a.update_by, a.update_time, a.remark, a.del_flag ) values (SEQ_PUBLIC.NEXTVAL, b.name, b.seq, b.purpose, b.spec, b.order_way, b.twining_num, b.in_time, b.scrap_time, b.scrap_reason, b.machine_id, b.create_by, sysdate, b.remark, '0' )
